import { useState } from 'react';
import { fmt } from '../utils/format';
import { STORES, BRANDS } from '../utils/config';

// Demo 資料
const DEMO_SALES = [
  { id:'MOMO-8529337-1', date:'2026-07-01', platform:'MOMO',           brand:'LEON',  code:'BDLN201', name:'麗容酵素入浴劑 880g',    qty:3, price:317, total:951 },
  { id:'MOMO-8529337-2', date:'2026-07-01', platform:'MOMO',           brand:'LEON',  code:'BDLN201', name:'麗容酵素入浴劑 880g',    qty:2, price:317, total:634 },
  { id:'MOMO-8529338-3', date:'2026-07-02', platform:'MOMO',           brand:'LEON',  code:'BDLN101', name:'麗容酵素入浴劑 600g',    qty:124,price:259,total:32116 },
  { id:'WEB-001',        date:'2026-07-05', platform:'TOOLA_SHOPLINE', brand:'TOOLA', code:'BDTL101', name:'多樂 B5 保濕修護霜',     qty:2, price:390, total:780 },
  { id:'WEB-002',        date:'2026-07-08', platform:'TOOLA_SHOPLINE', brand:'TOOLA', code:'BDTL301', name:'多樂慕絲－英國梨&麝香', qty:3, price:199, total:597 },
  { id:'SP-001',         date:'2026-07-10', platform:'TOOLA_SHOPEE',   brand:'TOOLA', code:'BDTL201', name:'多樂 嬰幼兒洗沐泡泡露', qty:5, price:220, total:1100 },
  { id:'ERP-001',        date:'2026-07-15', platform:'ERP',            brand:'LEON',  code:'BDLN101', name:'麗容酵素入浴劑 600g',    qty:936,price:160,total:149760 },
  { id:'ERP-002',        date:'2026-07-20', platform:'ERP',            brand:'TOOLA', code:'BDTL101', name:'多樂 B5 保濕修護霜',     qty:24, price:150, total:3600 },
];

const DEMO_RESTOCK = [
  { id:'RS-001', date:'2026-07-03', code:'BDLN201', name:'麗容酵素入浴劑 880g',    brand:'LEON',  qty:200, cost:186, vendor:'原廠', note:'7月補貨' },
  { id:'RS-002', date:'2026-07-05', code:'BDTL101', name:'多樂 B5 保濕修護霜',     brand:'TOOLA', qty:100, cost:150, vendor:'原廠', note:'' },
  { id:'RS-003', date:'2026-07-12', code:'BDLN101', name:'麗容酵素入浴劑 600g',    brand:'LEON',  qty:500, cost:160, vendor:'原廠', note:'大量補貨' },
  { id:'RS-004', date:'2026-07-18', code:'BDTL301', name:'多樂慕絲－英國梨&麝香', brand:'TOOLA', qty:150, cost:62,  vendor:'原廠', note:'' },
];

export default function QueryPage() {
  const [queryType, setQueryType] = useState('sales'); // 'sales' | 'restock'
  const [dateFrom,  setDateFrom]  = useState('');
  const [dateTo,    setDateTo]    = useState('');
  const [codeFilter,setCodeFilter]= useState('');
  const [brandFilter,setBrandFilter] = useState('ALL');
  const [platFilter, setPlatFilter]  = useState('ALL');
  const [results,   setResults]   = useState(null);

  const handleQuery = () => {
    const data = queryType === 'sales' ? DEMO_SALES : DEMO_RESTOCK;
    const filtered = data.filter(r => {
      if (dateFrom && r.date < dateFrom) return false;
      if (dateTo   && r.date > dateTo)   return false;
      if (codeFilter && !r.code.toLowerCase().includes(codeFilter.toLowerCase()) && !r.name.includes(codeFilter)) return false;
      if (brandFilter !== 'ALL' && r.brand !== brandFilter) return false;
      if (queryType === 'sales' && platFilter !== 'ALL' && r.platform !== platFilter) return false;
      return true;
    });
    setResults(filtered);
  };

  const totalQty   = results?.reduce((s, r) => s + r.qty, 0) || 0;
  const totalAmt   = results?.reduce((s, r) => s + (r.total || r.qty * r.cost), 0) || 0;

  return (
    <div>
      {/* 查詢類型 */}
      <div style={{ display:'flex', gap:6, marginBottom:16 }}>
        {[
          { id:'sales',   label:'銷貨查詢' },
          { id:'restock', label:'入庫查詢' },
        ].map(t => (
          <button key={t.id}
            className={`btn ${queryType===t.id ? 'btn-primary' : 'btn-ghost'}`}
            onClick={() => { setQueryType(t.id); setResults(null); }}>
            {t.label}
          </button>
        ))}
      </div>

      {/* 查詢條件 */}
      <div className="card mb-16">
        <div className="card-title">查詢條件</div>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12, marginBottom:14 }}>
          <div>
            <label className="form-label">起始日期</label>
            <input className="form-input" type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)}/>
          </div>
          <div>
            <label className="form-label">結束日期</label>
            <input className="form-input" type="date" value={dateTo} onChange={e => setDateTo(e.target.value)}/>
          </div>
          <div>
            <label className="form-label">產品代號 / 品名</label>
            <input className="form-input" placeholder="例：BDLN201 或 入浴劑"
              value={codeFilter} onChange={e => setCodeFilter(e.target.value)}/>
          </div>
          <div>
            <label className="form-label">品牌</label>
            <select className="form-input" value={brandFilter} onChange={e => setBrandFilter(e.target.value)}>
              <option value="ALL">全部品牌</option>
              {['TOOLA','LEON','TAKUYA'].map(b => (
                <option key={b} value={b}>{BRANDS[b]?.name || b}</option>
              ))}
            </select>
          </div>
          {queryType === 'sales' && (
            <div>
              <label className="form-label">銷售平台</label>
              <select className="form-input" value={platFilter} onChange={e => setPlatFilter(e.target.value)}>
                <option value="ALL">全部平台</option>
                {STORES.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
            </div>
          )}
        </div>
        <div style={{ display:'flex', gap:8 }}>
          <button className="btn btn-primary" onClick={handleQuery} style={{ flex:1, justifyContent:'center' }}>
            ◈ 開始查詢
          </button>
          <button className="btn btn-ghost" onClick={() => {
            setDateFrom(''); setDateTo(''); setCodeFilter('');
            setBrandFilter('ALL'); setPlatFilter('ALL'); setResults(null);
          }}>清除條件</button>
        </div>
      </div>

      {/* 查詢結果 */}
      {results !== null && (
        <div className="card">
          <div className="card-title">
            查詢結果
            <div style={{ display:'flex', gap:16, fontSize:14 }}>
              <span style={{ color:'var(--cyan)' }}>共 {results.length} 筆</span>
              <span style={{ color:'var(--yellow)' }}>數量合計：{fmt.number(totalQty)}</span>
              <span style={{ color:'var(--green)' }}>金額合計：{fmt.currency(totalAmt)}</span>
            </div>
          </div>

          {results.length === 0 ? (
            <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)', fontSize:16 }}>
              ◻ 查無符合條件的資料
            </div>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>日期</th>
                    <th>{queryType === 'sales' ? '訂單編號' : '入庫單號'}</th>
                    <th>{queryType === 'sales' ? '平台' : '廠商'}</th>
                    <th>品牌</th>
                    <th>產品代號</th>
                    <th>品名</th>
                    <th style={{ textAlign:'right' }}>數量</th>
                    <th style={{ textAlign:'right' }}>{queryType === 'sales' ? '售價' : '成本'}</th>
                    <th style={{ textAlign:'right' }}>金額</th>
                  </tr>
                </thead>
                <tbody>
                  {results.map((r, i) => {
                    const brand = BRANDS[r.brand];
                    const store = STORES.find(s => s.id === r.platform);
                    return (
                      <tr key={i}>
                        <td className="td-mono" style={{ color:'var(--muted)', fontSize:13 }}>{r.date}</td>
                        <td className="td-mono" style={{ color:'var(--cyan)', fontSize:12 }}>{r.id}</td>
                        <td>
                          <span style={{ fontSize:12, color: store?.color || 'var(--muted)', background:`${store?.color||'#888'}15`, padding:'2px 7px', borderRadius:3 }}>
                            {store?.name || r.platform || r.vendor || '–'}
                          </span>
                        </td>
                        <td>
                          <span style={{ fontSize:12, color:brand?.color||'var(--muted)', background:brand?.bg, padding:'2px 6px', borderRadius:3 }}>
                            {brand?.name?.split(' ')[0] || r.brand}
                          </span>
                        </td>
                        <td className="td-mono" style={{ color:'var(--cyan)', fontSize:12, fontWeight:700 }}>{r.code}</td>
                        <td style={{ maxWidth:160, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{r.name}</td>
                        <td className="td-right td-mono" style={{ fontWeight:600 }}>{fmt.number(r.qty)}</td>
                        <td className="td-right td-mono" style={{ color:'var(--muted)' }}>{fmt.currency(r.price || r.cost)}</td>
                        <td className="td-right td-mono" style={{ color:'var(--green)', fontWeight:600 }}>{fmt.currency(r.total || r.qty * r.cost)}</td>
                      </tr>
                    );
                  })}
                </tbody>
                <tfoot>
                  <tr style={{ background:'rgba(0,245,255,0.06)', borderTop:'2px solid var(--cyan)' }}>
                    <td colSpan={6} style={{ fontFamily:'var(--title)', fontWeight:700, color:'var(--cyan)', letterSpacing:2, padding:'11px 14px' }}>合計</td>
                    <td className="td-right td-mono" style={{ fontWeight:700, color:'var(--yellow)' }}>{fmt.number(totalQty)}</td>
                    <td></td>
                    <td className="td-right td-mono" style={{ fontWeight:700, color:'var(--green)' }}>{fmt.currency(totalAmt)}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}